// Tự động giải mã sang ArrayBuffer khi khởi chạy
const EMBEDDED_TEMPLATE_B64 = "";

function getEmbeddedTemplateBuffer() {
  const binaryString = atob(EMBEDDED_TEMPLATE_B64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

if (typeof window !== 'undefined') {
  window.getEmbeddedTemplateBuffer = getEmbeddedTemplateBuffer;
}
if (typeof global !== 'undefined') {
  global.getEmbeddedTemplateBuffer = getEmbeddedTemplateBuffer;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { getEmbeddedTemplateBuffer };
}
